function toDamageTypeLabel(typeKey: string | null | undefined): string {
    const value = String(typeKey || '').trim().toLowerCase();
    if (!value) return 'Unknown';
    return value.charAt(0).toUpperCase() + value.slice(1);
}

const DAMAGE_TYPES_FOR_ACHIEVEMENTS = Object.values(TYPES).map(v => String(v).toLowerCase());

for (let ti = 0; ti < DAMAGE_TYPES_FOR_ACHIEVEMENTS.length; ti++) {
    const typeKey = DAMAGE_TYPES_FOR_ACHIEVEMENTS[ti];
    if (typeKey == null) continue;
    const typeLabel = toDamageTypeLabel(typeKey);
    for (let li = 0; li < DAMAGE_TYPE_ACHIEVEMENT_LEVELS.length; li++) {
        const level = DAMAGE_TYPE_ACHIEVEMENT_LEVELS[li];
        if (!level) continue;
        const id = `typedDamage_${typeKey}_${li + 1}`;
        (ACHIEVEMENTS as Record<string, Record<string, unknown>>)[id] = {
            title: `${typeLabel} Specialist ${level.roman}`,
            desc: `Deal ${AMT(level.target)} ${typeLabel}-type damage`,
            target: level.target,
            trackingKey: `typedDamageDealt_${typeKey}`,
            rewards: level.rewards
        };
    }
}

