export const ACHIEVEMENTS_BY_TRACKING_KEY = (() => {
    const index = Object.create(null) as Record<string, [string, Record<string, unknown>][]>;
    for (const id in ACHIEVEMENTS) {
        const def = (ACHIEVEMENTS as Record<string, Record<string, unknown>>)[id];
        if (!def) continue;
        const key = String(def.trackingKey);
        if (!key || key === 'undefined') continue;
        if (!index[key]) index[key] = [];
        index[key].push([id, def]);
    }
    return index;
})();
if (typeof window !== 'undefined') (window as unknown as Record<string, unknown>).ACHIEVEMENTS_BY_TRACKING_KEY = ACHIEVEMENTS_BY_TRACKING_KEY;

