const LATE_GENERIC_SKIN_INDICES = Object.keys(LATE_GENERIC_SKIN_CONFIG)
    .map((k) => Number(k))
    .filter((n) => Number.isFinite(n))
    .sort((a, b) => a - b);

for (const skinIndex of LATE_GENERIC_SKIN_INDICES) {
    const cfg = (LATE_GENERIC_SKIN_CONFIG as Record<number, Record<string, unknown>>)[skinIndex];
    if (!cfg) continue;
    const unlockCondition = (cfg.unlockCondition as Record<string, unknown> | undefined)
        ?? (cfg.achievementId
            ? { type: 'achievement', id: String(cfg.achievementId) }
            : null);
    const unlockAchievementId = unlockCondition?.type === 'achievement'
        ? String(unlockCondition.id)
        : (cfg.achievementId ? String(cfg.achievementId) : null);
    let description = 'Additional header skin slot.';
    if (typeof cfg.achievementTitle === 'string' && cfg.achievementTitle) {
        description = `Unlocked via ${cfg.achievementTitle}.`;
    } else if (unlockCondition?.type === 'storyQuest') {
        description = 'Unlocked by completing a story quest.';
    } else if (unlockCondition?.type === 'stat' || unlockCondition?.type === 'pokedexUnique') {
        description = 'Unlocked by reaching a gameplay milestone.';
    } else if (unlockCondition?.type === 'achievement') {
        description = 'Unlocked via an achievement.';
    }
    (HEADER_SKINS as Record<string, Record<string, unknown>>)[`skin_${skinIndex}`] = {
        id: `skin_${skinIndex}`,
        name: cfg.name || `Skin ${skinIndex}`,
        description,
        unlockAchievementId,
        unlockCondition,
        imagePath: `img/header-skins/skin-${skinIndex}.webp`,
        colors: {
            bg: '#243447',
            border: '#16202a',
            panelBg: '#c3d4e6',
            panelBorder: '#3f5f7c',
            titleColor: '#e6f0ff',
            overlay: 'rgba(22,32,42,0.20)',
            glow: 'rgba(59,130,246,0.24)'
        }
    };
}

for (const skinId in HEADER_SKINS) {
    if (!Object.prototype.hasOwnProperty.call(HEADER_SKINS, skinId)) continue;
    const skin = (HEADER_SKINS as Record<string, Record<string, unknown>>)[skinId];
    if (!skin || typeof skin.imagePath !== 'string') continue;
    if (skin.imagePath.startsWith('img/header-skins/') && skin.imagePath.endsWith('.png')) {
        skin.imagePath = skin.imagePath.replace(/\.png$/, '.webp');
    }
}


