/**
 * @file src/lib/achievementDescFormat.ts
 * Format achievement description amounts/durations (aligned with achievement progress UI).
 */

import { formatNumber, formatTimeString } from '../../formatters.ts';

const BILLION = 1_000_000_000;

export const TIME_ACHIEVEMENT_TRACKING_KEYS = new Set([
    'totalPlayTime',
    'offlineTimeSimulatedMs',
    'incubatorClickTotalMs',
    'incubatorAutoClickTotalMs',
    'rocketLoanActiveRealtimeMs',
]);

export function formatAchievementAmount(target: number): string {
    const n = Number(target);
    if (!Number.isFinite(n)) return '0';
    if (Math.abs(n) >= BILLION) return formatNumber(n);
    return n.toLocaleString('en-US');
}

export function formatAchievementDuration(ms: number): string {
    return formatTimeString(Math.max(0, Number(ms) || 0));
}

/** French display: compact suffixes at 1B+, locale below. */
export function formatAchievementAmountFr(target: number): string {
    const n = Number(target);
    if (!Number.isFinite(n)) return '0';
    if (Math.abs(n) >= BILLION) return formatNumber(n);
    return n.toLocaleString('fr-FR');
}

export function formatAchievementDurationFr(ms: number): string {
    return formatAchievementDuration(ms);
}
